async function api(path:string,opt:any={}){const r=await fetch(path,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){const err:any=new Error(d.error||'Request failed');err.status=r.status;err.data=d;throw err}return d}
function trackClick(action:string){try{fetch('/api/track-click',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action}),keepalive:true}).catch(()=>{})}catch{}}
function notify(message:string,type:'error'|'success'='error'){window.dispatchEvent(new CustomEvent('ip-notice',{detail:{message,type}}))}
function NoticeHost(){const[n,setN]=useState<any>(null);useEffect(()=>{const h=(e:any)=>{setN(e.detail);window.setTimeout(()=>setN(null),5200)};window.addEventListener('ip-notice',h);return()=>window.removeEventListener('ip-notice',h)},[]);if(!n)return null;return <div className={`adminNotice ${n.type==='success'?'success':'error'}`} role="status"><div><b>{n.type==='success'?'Done':'Something went wrong'}</b><span>{n.message}</span></div><button onClick={()=>setN(null)} aria-label="Dismiss">×</button></div>}
function ConfirmModal({open,title,message,confirmLabel='Delete',onCancel,onConfirm}:{open:boolean,title:string,message:string,confirmLabel?:string,onCancel:()=>void,onConfirm:()=>void}){useEffect(()=>{if(!open)return;const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')onCancel()};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[open,onCancel]);if(!open)return null;return <div className="confirmBackdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onCancel()}}><div className="confirmModal" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><button className="confirmClose" type="button" onClick={onCancel} aria-label="Close">×</button><div className="confirmEyebrow">CONFIRM ACTION</div><h2 id="confirm-title">{title}</h2><p>{message}</p><div className="confirmActions"><button className="btn outline" type="button" onClick={onCancel}>Cancel</button><button className="btn dangerButton" type="button" onClick={onConfirm}>{confirmLabel}</button></div></div></div>}

function phoneLink(p:string){return`tel:+91${p}`}
function formatCareerDate(value:string){if(!value)return'';const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return value;return `${m[3]}/${m[2]}/${m[1]}`}
function normalizeCareerDateInput(value:string){const digits=value.replace(/\D/g,'').slice(0,8);if(digits.length<=2)return digits;if(digits.length<=4)return `${digits.slice(0,2)}/${digits.slice(2)}`;return `${digits.slice(0,2)}/${digits.slice(2,4)}/${digits.slice(4)}`}
function careerDateToIso(value:string){const m=value.trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(!m)return value.trim()?null:'';const day=Number(m[1]),month=Number(m[2]),year=Number(m[3]);const d=new Date(Date.UTC(year,month-1,day));if(d.getUTCFullYear()!==year||d.getUTCMonth()!==month-1||d.getUTCDate()!==day)return null;return `${year.toString().padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function extractYoutubeId(value:string){try{const u=new URL(value);if(u.hostname.includes('youtu.be'))return u.pathname.slice(1).split('/')[0];if(u.searchParams.get('v'))return u.searchParams.get('v')||'';return u.pathname.match(/\/(?:embed|shorts|live)\/([^/?]+)/)?.[1]||''}catch{return''}}
function normalizeTagText(s:string){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function normalizeHashtagText(s:string){return String(s||'').trim().replace(/^#+/,'').toLowerCase()}
function extractCaptionHashtags(caption:string):string[]{return Array.from(new Set((String(caption||'').match(/#[\p{L}0-9_-]+/gu)||[]).map(t=>normalizeHashtagText(t))))}
function extractInstagramId(value:string){try{const u=new URL(value);if(!/instagram\.com$/i.test(u.hostname)&&!/\.instagram\.com$/i.test(u.hostname))return'';return u.pathname.match(/\/reel\/([^/?#]+)/)?.[1]||''}catch{return''}}
function normalizeVideo(v:any){const platform=v.platform||(/instagram\.com/i.test(v.source_url||v.embed_url||'')?'instagram':'youtube');if(platform==='youtube'){const id=v.video_id||extractYoutubeId(v.source_url||v.embed_url||'');return{...v,platform,video_id:id}}if(platform==='instagram'){const id=extractInstagramId(v.source_url||v.embed_url||'')||v.video_id;return{...v,platform,video_id:id}}return{...v,platform:'youtube',video_id:extractYoutubeId(v.source_url||'')}}

